<?php /* * ========================================================= * api/mark_private_read.php * * Пометка входящих личных сообщений как прочитанных. * * PHP 5.6.4 * * is_read = 0 -> непрочитано * is_read = 1 -> прочитано * ========================================================= */ ini_set('display_errors', 1); ini_set('display_startup_errors', 1); error_reporting(E_ALL); require_once __DIR__ . '/../config/auth.php'; requireLogin(); checkBlocked(); updateLastActivity(); header('Content-Type: application/json; charset=utf-8'); /* * ========================================================= * ТОЛЬКО POST * ========================================================= */ if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); echo json_encode( array( 'success' => false, 'error' => 'Недопустимый метод запроса.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ТЕКУЩИЙ ПОЛЬЗОВАТЕЛЬ * ========================================================= */ $myId = (int) currentUserId(); /* * ========================================================= * ПОЛЬЗОВАТЕЛЬ, ЧЕЙ ДИАЛОГ ОТКРЫТ * ========================================================= */ $senderId = isset($_POST['user_id']) ? (int) $_POST['user_id'] : 0; if ($senderId <= 0) { echo json_encode( array( 'success' => false, 'error' => 'Не указан пользователь.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * Нельзя помечать сообщения самому себе. */ if ($senderId === $myId) { echo json_encode( array( 'success' => false, 'error' => 'Некорректный пользователь.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПРОВЕРЯЕМ, ЧТО ПОЛЬЗОВАТЕЛЬ СУЩЕСТВУЕТ * ========================================================= */ $stmt = $pdo->prepare( 'SELECT id FROM users WHERE id = ? LIMIT 1' ); $stmt->execute( array( $senderId ) ); if (!$stmt->fetch()) { echo json_encode( array( 'success' => false, 'error' => 'Пользователь не найден.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * ========================================================= * ПОМЕЧАЕМ НЕПРОЧИТАННЫЕ СООБЩЕНИЯ * ========================================================= * * ВАЖНО: * * sender_id = выбранный собеседник * receiver_id = текущий пользователь * * Меняем только: * * is_read = 0 * * Уже прочитанные сообщения: * * is_read = 1 * * НЕ ЗАТРАГИВАЮТСЯ. * ========================================================= */ try { $stmt = $pdo->prepare( 'UPDATE personal_messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ? AND is_read = 0' ); $stmt->execute( array( $senderId, $myId ) ); /* * Количество реально изменённых записей. */ $updated = $stmt->rowCount(); /* * ===================================================== * ТАКЖЕ СИНХРОНИЗИРУЕМ private_messages * ===================================================== * * Если сообщение уже есть в основном приватном чате, * оно также становится прочитанным. */ $stmt = $pdo->prepare( 'UPDATE private_messages SET is_read = 1 WHERE sender_id = ? AND receiver_id = ? AND is_read = 0' ); $stmt->execute( array( $senderId, $myId ) ); /* * ===================================================== * ОТВЕТ * ===================================================== */ echo json_encode( array( 'success' => true, 'updated' => (int) $updated ), JSON_UNESCAPED_UNICODE ); exit; } catch (Exception $e) { echo json_encode( array( 'success' => false, 'error' => 'Не удалось отметить сообщения прочитанными.' ), JSON_UNESCAPED_UNICODE ); exit; } ?>